(()=>{'use strict';
const $=s=>document.querySelector(s),page=document.body.dataset.page,C=window.HEXU_SITE||{},main=$('#main');let catalog=[],loaded=false,loadError=false;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=v=>{if(!v)return '';try{const u=new URL(v,location.origin);return ['https:','http:'].includes(u.protocol)&&(u.origin===location.origin||u.protocol==='https:')?u.href:'';}catch{return '';}};
const a=(label,href,cls='')=>`<a class="btn ${cls}" href="${e(url(href)||'#')}">${e(label)}</a>`;
const section=(title,body,desc='',cls='')=>`<section class="section ${cls}"><div class="wrap"><div class="heading"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div></div>${body}</div></section>`;
const title=(t,d)=>`<div class="section-title"><div class="wrap"><div class="breadcrumbs"><a href="index.html">首页</a> / ${e(t)}</div><h1>${e(t)}</h1><p>${e(d)}</p></div></div>`;
const photo=(src,alt)=>src&&url(src)?`<img class="picture" src="${e(url(src))}" alt="${e(alt)}" loading="lazy">`:`<div class="photo-empty">${e(alt||'图片资料待发布')}</div>`;
const card=(h,b,tag='',src='',buttons='')=>`<article class="card">${src?photo(src,h):''}<div class="card-body">${tag?`<span class="tag">${tag}</span>`:''}<h3>${h}</h3><p>${b}</p>${buttons?`<div class="actions">${buttons}</div>`:''}</div></article>`;
const empty=(h,b,buttons='')=>`<div class="empty"><h3>${h}</h3><p>${b}</p>${buttons?`<div class="actions">${buttons}</div>`:''}</div>`;
const videoBlock=(heading='一分钟，了解怎样开始')=>section(heading,`<div class="video-panel"><div><video id="platformVideo" controls playsinline preload="metadata" poster="assets/order-guide-poster.png"><source src="assets/order-quick-guide.mp4" type="video/mp4"></video><p class="caption" id="videoNote">顾客下单演示 · 35秒快看，实际操作以正式系统为准。</p></div><div class="video-list" id="videoList"><p class="eyebrow">平台演示</p><button data-video-src="assets/order-quick-guide.mp4" aria-pressed="true">顾客如何下单 · 35秒</button><div id="publishedVideos"></div><div class="actions">${a('查看服务指南','service-guide.html','secondary')}</div></div></div>`);
const banner=()=>`<div class="band"><div><h2>把你的资源，变成共同的服务</h2><p>门店、个体专业人员、机构与培训团队，欢迎了解合作。</p></div>${a('联系合作','cooperation-apply.html','gold')}</div>`;
const sampleStore=()=>`<div class="photo-stack"><img src="assets/community-storefront.png" alt="荷序社区数字门店门头样板"><div class="signboard"><strong>荷序健康</strong><span>女性健康社区数字门店</span></div><img src="assets/community-interior.png" alt="社区数字门店内部空间样板"><p class="caption">社区数字门店空间样板 · 展示未来共建方向</p></div>`;
const locked=(heading,scope)=>`<div class="lock"><div><span class="lock-label">合作后授权访问</span><h2>${heading}</h2><p>操作手册、协议模板和项目技术资料，按合作身份与对应项目开通。未授权账号无法读取或下载文件。</p><div class="actions">${a('申请开通','cooperation-apply.html?interest=training','gold')}</div></div><form id="unlockForm"><label>合作解锁码（如平台已提供）<input name="code" type="password" maxlength="120" autocomplete="off" placeholder="输入平台提供的解锁码"></label><div class="actions"><button class="btn gold" type="submit">验证解锁码</button><button type="button" class="btn secondary" id="checkAccess">验证账号权限</button></div><p id="unlockStatus" class="status" role="status"></p></form></div><div id="authorizedFiles" data-scope="${scope}" class="grid" style="margin-top:24px"></div>`;
const regionFields=()=>`<div class="full"><label>所在地区 *</label><div class="region"><select id="province" required aria-label="省份"><option value="">选择省份</option></select><select id="city" required disabled aria-label="城市"><option value="">选择城市</option></select><select id="county" required disabled aria-label="区县"><option value="">选择区县</option></select></div></div>`;
const basicFields=()=>`<label>姓名 *<input name="name" required minlength="2" maxlength="40" autocomplete="name" placeholder="您的姓名"></label><label>联系方式 *<input name="phone" type="tel" required pattern="1[3-9][0-9]{9}" maxlength="11" autocomplete="tel" placeholder="11位手机号码"></label>`;
const consent=()=>`<label class="trap" aria-hidden="true">网站<input name="website" tabindex="-1" autocomplete="off"></label><label class="check"><input name="consent" type="checkbox" required><span>我同意荷序平台为处理本次申请使用所填资料并联系我。请勿填写病历、身份证号或银行卡号。</span></label>`;
const applyForm=join=>`<div class="forms"><h2>${join?'共建数字门店意向登记':'合作意向登记'}</h2><p class="muted">${join?'留下所在地区，团队与你沟通门店资源与共建方向。':'先了解你的资源与期望，再共同确定合作项目。'}</p><form id="applicationForm" data-join="${join}"><div class="fields" style="margin-top:22px">${basicFields()}${!join?`<label class="full">合作身份 *<select name="applicantType" id="applicantType"><option value="personal">个人</option><option value="individual">个体专业人员</option><option value="store">门店 / 商户</option><option value="other">其他（机构或团队等）</option></select></label><label class="full" id="otherField" hidden>请具体说明<input name="otherType" id="otherType" maxlength="120" disabled></label>`:''}${regionFields()}${!join?`<label class="full">希望合作的内容 *<select name="interest"><option value="tools">数字化运营工具</option><option value="ecosystem">项目体系共建</option><option value="products">服务产品设计</option><option value="training">技术培训与认证</option><option value="education">健康教育与顾问支持</option></select></label><label class="full">资源与合作需求 *<textarea name="message" required minlength="10" maxlength="1500" rows="4" placeholder="请说明专长、门店或机构资源，以及希望开展的合作（至少10字）"></textarea></label>`:''}</div>${consent()}<button type="submit" class="btn">提交${join?'共建意向':'合作申请'}</button><p class="status" id="applicationStatus" role="status"></p></form></div>`;
function home(){return `<section class="hero hero-carousel" aria-label="荷序平台介绍" aria-roledescription="轮播"><div class="wrap"><div class="hero-slides"><article class="hero-slide active" data-hero-slide="0"><p class="eyebrow">荷序健康 · 专业有序，温暖相伴</p><h1>让专业相连，<br>让健康服务更安心。</h1><p>女性身心健康综合服务数字平台<br>连接门店、专业人员与服务项目，陪伴每一个生活阶段。</p><div class="actions">${a('了解小荷','about.html')}${a('看看附近的服务','projects.html','secondary')}</div></article><article class="hero-slide" data-hero-slide="1" aria-hidden="true" inert><p class="eyebrow">服务清楚 · 选择安心</p><h1>从你的需求出发，<br>找到适合自己的服务。</h1><p>按城市了解精品项目，认识门店与专业人员。<br>让每一次服务更清楚、安心、有回应。</p><div class="actions">${a('查看精品项目','projects.html')}${a('认识优秀技师','service-display.html','secondary')}</div></article><article class="hero-slide" data-hero-slide="2" aria-hidden="true" inert><p class="eyebrow">资源相连 · 服务共建</p><h1>让专业有所施展，<br>让伙伴共同成长。</h1><p>把门店空间、专业能力与获客资源组织起来，<br>通过标准化和数字化协作，共同服务女性。</p><div class="actions">${a('了解合作','cooperation-apply.html')}${a('共建数字门店','join.html','secondary')}</div></article></div><div class="hero-controls"><button type="button" class="hero-prev">上一屏</button><div class="hero-dots" role="group" aria-label="选择展示屏">${[0,1,2].map(i=>`<button type="button" data-hero-dot="${i}" aria-label="第${i+1}屏" aria-pressed="${i===0}">${i+1}</button>`).join('')}</div><button type="button" class="hero-next">下一屏</button><button type="button" class="hero-toggle">暂停轮播</button><span id="heroStatus" class="sr-live" role="status" aria-live="polite"></span></div></div></section><div class="wrap quick">${[['01','我需要服务','进入客户端，预约服务',C.orderUrl||'client-entry.html'],['02','我需要合作','让资源共同发挥价值','cooperation-apply.html'],['03','积分兑换','小荷有礼，生活有喜','points.html']].map(([n,t,d,h])=>`<a href="${h}"><span class="number">${n}</span><span><strong>${t}</strong><small>${d}</small></span></a>`).join('')}</div>${section('一个平台，连接多方专业力量',`<div class="split"><div class="copy"><p class="eyebrow">关于小荷</p><h2>荷序健康｜女性身心健康<br>综合服务数字平台</h2><p>荷序把门店空间、专业人员、服务项目和获客资源组织起来，通过标准化与数字化协作，共同服务女性，并按实际订单分配收益。</p><p class="editorial">让专业有场景，让门店有协作，<br>让顾客有清楚的服务路径。</p><div class="actions">${a('走近小荷','about.html','secondary')}</div></div>${sampleStore()}</div>`)}${section('从你的需求出发',`<div class="grid">${card('精品项目','按所在城市发现特色服务，了解内容、人员与项目标准。','服务选择','',a('选择城市','projects.html','secondary'))}${card('精品门店','认识服务环境、门店专长与已发布的服务项目。','社区附近','',a('逛逛门店','stores.html','secondary'))}${card('健康咨询','阅读科普，认识公益专业顾问，找到咨询指引。','知识与支持','',a('查看健康咨询','health.html','secondary'))}</div>`,'先看清信息，再选择适合自己的服务。','alt')}${videoBlock()}${section('一起把服务做好',banner())}`;}
function about(){return title('关于小荷','荷序健康｜女性身心健康综合服务数字平台')+section('我们的理念',`<div class="split"><div class="copy"><p class="eyebrow">专业有序 · 温暖相伴</p><h2>把分散的资源，<br>组织成可以协作的服务。</h2><p>荷序把门店空间、专业人员、服务项目和获客资源组织起来，通过标准化与数字化协作，共同服务女性，并按实际订单分配收益。</p><p>顾客可以更清楚地了解服务、门店与人员；伙伴可以围绕同一个项目，明确分工、流程与服务记录。</p><div class="actions">${a('联系我们共建数字门店','join.html')}</div></div>${sampleStore()}</div>`)+section('我们共同坚持',`<div class="grid">${card('尊重每一位女性','从真实需求出发，尊重选择、保护隐私，让服务有温度。','以人为本')}${card('尊重专业与标准','严选项目，共建SOP，培训与考核后交付，持续复盘改进。','专业共建')}${card('协作清楚，有据可循','把人员、门店、渠道与订单关联起来，按正式约定核算收益。','数字协作')}</div>`,'让每一次服务更清楚、安心、有回应。','alt')+section('愿景：走进社区，连接更多生活阶段',`<div class="steps">${[['项目共建','先筛选专业人员与门店，把一个项目服务做稳。'],['本地生态','逐步形成培训、项目、服务与顾问协作网络。'],['社区数字门店','与成熟伙伴共建便利、规范、有温度的社区服务点。'],['城市与商城','运营稳定后，拓展城市协作与小荷积分商城。']].map(([t,d])=>`<article class="step"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><p class="caption">建设方向分阶段推进，具体服务、资源与合作支持以实际公布为准。</p>`)+cooperationScreen()+section('欢迎一起共建',`<div class="band"><div><h2>在社区，共同建立值得信任的服务点</h2><p>有门店、有专业、愿意共同建立标准，欢迎留下你的意向。</p></div>${a('联系我们共建数字门店','join.html','gold')}</div>`);}
function guide(){return title('服务指南','顾客清楚下单，伙伴清楚合作，服务过程清楚可循。')+`<div class="wrap tabs"><button class="active" data-guide="customer">顾客如何点单</button><button data-guide="partner">商家如何合作</button><button data-guide="operations">合作后操作指南</button></div><div id="guideView"></div>`;}
const guideCustomer=()=>section('四步找到适合的服务',`<div class="steps">${[['选择城市与项目','了解服务内容、适用场景、价格与预约要求。'],['选择门店与技师','核对服务地点、专业人员和可预约安排。'],['确认订单','选择了解渠道，确认项目次数与订单说明。'],['到店服务与反馈','按约定接受服务，核销后查看记录并留下反馈。']].map(([t,d])=>`<article class="step"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="actions">${a('查看精品项目','projects.html')}${C.orderUrl?a('进入正式点单',C.orderUrl,'secondary'):a('查看点单界面演示','order-design.html','secondary')}</div>${!C.orderUrl?'<p class="caption">正式点单入口待工程师配置；界面演示不产生真实订单或支付。</p>':''}`)+videoBlock('35秒，看懂下单')+section('服务前，请先把这些看清',`<details open><summary>项目内容与服务边界</summary><p>确认本次服务包含什么、适合什么场景、由谁提供。有医疗诊断、治疗或用药需求，请咨询具备相应资质的医疗机构。</p></details><details><summary>次数、核销与售后</summary><p>单次体验、三次、五次项目以实际订单为准，每次服务对应独立核销记录。预约、取消、退款及异常处理以正式订单条款和适用规定为准。</p></details><details><summary>遇到服务问题怎么办</summary><p>保留订单和服务记录，可通过“欢迎投诉”提交具体情况，平台联系相关各方核实并协调。</p><div class="actions">${a('欢迎投诉','disputes.html','secondary')}</div></details>`);
const guidePartner=()=>section('从申请，到首个合作项目',`<div class="steps">${[['提交意向','说明身份、地区、联系方式和希望合作的内容。'],['评估资源','核对专长、资质、门店空间设备与合作需求。'],['明确合作','确认项目、培训、费用、分工与书面条款。'],['培训与验证','配置权限，完成培训考核，验证首笔服务流程。']].map(([t,d])=>`<article class="step"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="actions">${a('申请合作','cooperation-apply.html')}</div>`)+`<section class="section alt"><div class="wrap"><h2>平台支持与合作说明</h2><div id="cooperationServices" style="margin-top:24px"></div></div></section>`+section('公开资料与授权模板',locked('合作资料访问','partner'));
const guideOperations=()=>section('合作后平台操作指南',locked('从资料配置，到订单核销','partner'))+section('合作伙伴上手路径',`<div class="grid">${card('资料与项目配置','确认门店、人员、项目介绍、价格、预约与交付说明。','01')}${card('订单与服务衔接','学习接单、排期、现场接待及按次核销流程。','02')}${card('记录与收益核对','查看权限内的订单与分配记录，按规则处理评价和售后。','03')}</div><div class="notice">具体后台画面、操作视频、协议和手册将在合作后按账号权限开放。</div>`);
function stores(){return title('查看门店','认识门店环境与擅长项目，选择适合自己的服务场景。')+section('精品合作门店',`<div class="filters"><label for="storeCity">所在地区</label><select id="storeCity"><option value="all">全部地区</option></select>${a('联系合作','cooperation-apply.html','secondary')}</div><p id="storeStatus" class="caption" role="status">正在读取已发布门店…</p><div id="storeGrid" class="grid" style="margin-top:20px"></div><div class="actions"><button id="moreStores" class="btn secondary">查看更多门店</button></div><div class="actions"><a class="btn secondary" id="storeAdmin" href="stores-admin.html" hidden>录入与发布门店</a></div>`,'优先呈现三家重点门店；真实资料审核发布后更新。')+section('门店空间展示样板',`<div class="split">${sampleStore()}<div class="copy"><span class="tag sample">空间样板</span><h2>熟悉的社区，安心的服务。</h2><p>门头与内部图片展示社区数字门店的空间方向。样板不计入已入驻门店，实际门店以审核发布资料为准。</p><div class="actions">${a('联系合作','cooperation-apply.html')}</div></div></div>`,'','alt')+section('一起把你的门店优势展示出来',banner());}
const samples=[{id:'s1',kind:'project',title:'母婴照护服务项目',city:'南通',description:'呈现项目服务内容、适用场景、服务时长、专业人员要求与预约说明。此条用于布局演示，不代表项目已经开放。',image:'assets/order-operation-sample.png',tags:'母婴支持,服务内容,预约说明',sop:'SOP版本展示位',sample:true},{id:'s2',kind:'project',title:'女性身心支持项目',city:'南通',description:'展示专业服务与健康教育的组合方式。正式项目需经审核后发布，并关联实际门店与服务人员。',tags:'身心关怀,专业共建',sop:'SOP版本展示位',sample:true},{id:'s3',kind:'project',title:'城市特色服务项目',city:'苏州',description:'不同城市可以筛选当地优质特色服务，形成项目模板。城市与项目均为筛选效果演示。',tags:'本地特色,标准化',sop:'SOP版本展示位',sample:true}];
function projects(){return title('精品项目','按城市发现已发布的特色服务项目，查看项目介绍与标准信息。')+section('选择你的服务城市',`<div class="filters"><label for="projectCity">服务城市</label><select id="projectCity"><option value="all">全部已开展城市</option></select><button class="btn secondary" id="projectSample">查看展示样例</button></div><p class="caption" id="projectStatus" role="status">正在读取项目目录…</p><div id="projectGrid" class="grid" style="margin-top:24px"></div>`,`城市列表随已审核发布的项目更新。`)+projectScenes()+section('你有特色项目，欢迎共同打磨',banner());}
function training(){return title('技术培训','共建项目体系、技术SOP与专业标准，让规范服务持续落地。')+section('项目培训与标准资料',locked('对应项目，开通对应权限','training'))+section('从项目体系，到标准化交付',`<div class="scroll-strip">${card('项目体系共建','明确目标人群、场景、服务边界与项目组合。','体系设计')}${card('SOP与专业标准','共同制定操作流程、记录要求、质量检查与异常处理。','流程标准')}${card('示范、演练与考核','讲解、示范、情景演练与能力评估形成记录。','培训实施')}${card('复训与版本更新','项目标准更新后同步培训，依据反馈持续改进。','持续成长')}</div>`,'完整技术资料仅向已获对应项目授权的人员开放。','alt')+section('各地区优秀技术人员',`<div class="filters"><label for="techCity">服务城市</label><select id="techCity"><option value="all">全部地区</option></select></div><div id="technicianGrid" class="grid"></div>`,'核验专业资料并取得展示授权后发布。')+section('专业共创，欢迎加入',banner());}
function showcase(){return title('服务展示','看见专业人员，也看见服务发生的场景。')+section('各地区优秀技师',`<div class="filters"><label for="techCity">所在城市</label><select id="techCity"><option value="all">全部地区</option></select>${a('技师申请加入','cooperation-apply.html?interest=training','secondary')}</div><div id="technicianGrid" class="grid"></div>`,'展示已核验的专业介绍、项目专长与服务地区。')+section('真实服务场景',`<div id="sceneGrid" class="grid"></div>`,'服务场景与介绍，审核后按所在城市展示。','alt')+section('服务场景展示样例',`<div class="grid">${card('服务前沟通','了解需求、确认服务内容，做好必要告知与准备。','场景样例','assets/community-interior.png')}${card('专业服务交付','按对应项目流程完成交付，做好操作与服务记录。','场景样例','assets/order-operation-sample.png')}${card('社区服务空间','清楚的接待与服务分区，让专业人员和顾客顺畅衔接。','空间样板','assets/community-storefront.png')}</div><p class="caption">以上图片用于场景版式展示，实际服务案例以审核发布资料为准。</p>`)+section('服务路径 SOP',`<div class="steps">${[['了解需求','沟通需求与服务适配'],['确认方案','明确项目、人员与预约'],['规范交付','按项目标准开展服务'],['记录反馈','核销记录与持续回访']].map(([t,d])=>`<article class="step"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`)+videoBlock('看看标准化服务如何开展')+section('你有专业，欢迎一起共创',banner());}
function health(){return title('健康咨询','专业知识与温暖支持，陪伴女性的每个生活阶段。')+section('公益专业健康顾问',`<div class="advisor-controls"><button class="btn secondary" id="advisorPrev">上一组</button><button class="btn secondary" id="advisorNext">下一组</button><button class="btn secondary" id="advisorPause">暂停轮播</button></div><div id="advisorGrid" class="scroll-strip advisor-strip"></div><p class="caption">顾问名单、照片与咨询安排，经本人授权和平台核验后公布。公益咨询不替代诊疗。</p>`)+section('小荷健康资讯',`<div class="health-layout"><div><div class="chips" id="healthTopics">${['全部','母婴与哺乳','盆底与产后','女性身心'].map((t,i)=>`<button class="${!i?'active':''}" data-topic="${t}">${t}</button>`).join('')}</div><div id="articleGrid" class="grid two"></div>${C.officialAccountUrl?`<div class="actions">${a('更多公众号资讯',C.officialAccountUrl,'secondary')}</div>`:''}</div><aside class="community-qr"><p class="eyebrow">与小荷保持联系</p><h2>让你的需求，<br>被认真听见。</h2><div id="communityQR" class="qr-slot">工作人员二维码待发布</div><p>添加工作人员，告诉我们更多需求。受邀加入女性健康社群，了解专家交流活动与预约安排。</p><p class="caption">具体专家与活动时间以平台公布为准。</p></aside></div>`);}

function points(){return title('小荷积分','小荷有礼，把每一次信任，延续到日常生活。')+`<section class="section"><div class="wrap"><div class="gift-title"><p class="eyebrow">小荷有礼</p><h1>积分兑换专区</h1><p>礼物不止一种，慢慢挑选生活所需。<br>积分无有效期，等到喜欢的好物有库存，再兑换。</p></div><div class="wallet" style="margin-top:24px"><article>可用积分<strong id="balance">—</strong></article><article>待入账积分<strong id="pending">—</strong></article><article>积分有效期<strong>长期有效</strong></article></div><p class="caption" id="walletStatus">账户入口待接入；此页不展示虚构余额或发放积分。</p><div class="actions">${a('查看积分明细','points-account.html','secondary')}</div><div class="heading" style="margin-top:32px"><div><h2>生活所需，小荷有礼</h2><p>仅面向符合规则的消费者与关联分享人兑换，不对外售卖。</p></div></div><div class="chips" id="giftCategories"></div><p id="giftStatus" class="caption" role="status"></p><div id="giftGrid" class="grid four"></div></div></section>`+section('积分规则，清楚可查',`<details open><summary>积分怎样获得？</summary><p>拟定规则：顾客与符合规则的关联分享人，各按计分金额的5%获得积分，100元对应各5积分。按每次已核销服务对应的实际计分金额计算，核销后满7天再入账；部分核销不按整单金额重复发放。正式开通时以订单及积分规则为准。</p></details><details><summary>积分怎样使用？</summary><p>1积分对应1元兑换价值；可兑换已上架礼品或按开放规则抵扣指定服务。积分无有效期，不支持提现。积分不足或商品缺货时暂不可兑换，有库存后可继续选择。</p></details><details><summary>配送与社区领取</summary><p>商品支持的领取方式以详情为准。社区领取点未设立时可选择邮寄；配送地区、运费与地址在确认兑换前说明。</p></details><details><summary>退款或服务争议如何处理？</summary><p>退款时按对应服务金额调整顾客及关联分享人的待入账或已入账积分。已使用积分造成的不足，由系统记录并依据正式规则协调处理。复杂争议可提交平台总部核实，不因线下协商而重复退款或重复发放。</p><div class="actions">${a('欢迎投诉','disputes.html','secondary')}</div></details>`)+videoBlock('看看怎样选择服务与查询记录');}
function disputes(){return title('欢迎投诉','你的每一次反馈，我们都认真对待。')+section('提交服务反馈与争议协调',`<div class="forms"><form id="disputeForm"><div class="fields">${basicFields()}<label class="full">关联订单编号 *<input name="orderRef" required maxlength="80" placeholder="从订单详情复制订单编号"></label><label class="full">您的身份<select name="role"><option value="customer">顾客本人</option><option value="referrer">关联分享人</option></select></label><label class="full">需要协调的情况 *<textarea name="description" required minlength="10" maxlength="1500" rows="5" placeholder="说明门店、项目、发生时间与具体问题。请勿填写敏感健康或资金账户资料。"></textarea></label></div>${consent()}<button class="btn" type="submit">提交平台总部</button><p id="formStatus" class="status" role="status"></p></form></div>`,'顾客本人及关联分享人均可提交，平台核实后联系相关各方。')+section('处理路径',`<div class="steps">${[['收到反馈','保留订单、服务与支付凭证，提交具体情况。'],['核实记录','核对订单、服务核销及相关人员反馈。'],['协调方案','复杂争议可线下协商应退费用并形成处理记录。'],['同步结果','同步更新订单与相关积分，避免重复处理。']].map(([t,d])=>`<article class="step"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="notice">提交不代表退款已经批准或支付。积分不支持提现；关联分享人不因关联订单自动享有现金退款。协商不成，可依法通过投诉、调解等途径解决。</div>`);}
function contact(){return title('联系我们','合作共建、门店加入、专业协作，欢迎和小荷聊聊。')+section('找到适合你的联系入口',`<div class="grid">${card('项目与专业合作','个人、个体、商户、机构，说明你的资源与合作方向。','合作共建','',a('填写合作申请','cooperation-apply.html'))}${card('共建社区数字门店','愿意共同建立标准化服务点，留下地区与联系方式。','门店共建','',a('登记共建意向','join.html'))}${card('服务反馈与投诉','消费、服务、退款或积分问题，提交订单相关情况。','顾客支持','',a('提交反馈','disputes.html'))}</div><div class="notice">${C.contactPhone?'联系电话：'+e(C.contactPhone):'联系电话与邮箱将在核验后公布。您可以先通过表单留下合作意向。'}${C.contactEmail?' · 邮箱：'+e(C.contactEmail):''}</div>`)+section('共建数字门店，快速联系',applyForm(true))+`<section class="section alt" id="contactAdmin" hidden><div class="wrap"><h2>待联系信息</h2><p class="caption">仅管理员可见</p><div id="pendingSummary" class="wallet" style="margin-top:20px"></div><div class="actions">${a('查看门店共建意向','contact.html#leadRecords','secondary')}${a('查看合作申请','guide-admin.html','secondary')}${a('查看服务反馈','contact.html#leadRecords','secondary')}</div><div id="leadRecords"></div></div></section>`;}
function admin(){return title('展示内容管理','发布城市项目、人员介绍、健康内容与演示视频。')+section('管理员资料录入',`<p id="adminStatus" class="status" role="status">正在验证管理员权限…</p><div id="adminPanel" hidden><div class="actions">${a('门店照片与资料','stores-admin.html','secondary')}${a('培训资料与账号授权','guide-admin.html','secondary')}${a('合作意向与投诉','contact.html#contactAdmin','secondary')}</div><form id="contentForm" class="forms" style="margin-top:24px"><input name="id" type="hidden"><div class="fields"><label>内容类型<select name="kind"><option value="project">精品项目</option><option value="technician">技术人员</option><option value="advisor">公益健康顾问</option><option value="article">科普文章 / 健康问题</option><option value="video">演示视频</option><option value="scene">服务场景</option><option value="qr">工作人员二维码</option><option value="gift">积分产品</option></select></label><label>城市<input name="city" maxlength="50" placeholder="例：南通"></label><label class="full">标题 / 姓名<input name="title" required minlength="2" maxlength="100"></label><label class="full">介绍与说明<textarea name="description" required minlength="10" maxlength="3000" rows="5"></textarea></label><label>分类标签（积分产品填写分类编号；视频填写about或showcase；技师填priority:1等排序值）<input name="tags" maxlength="300" placeholder="例：母婴与哺乳,公益咨询"></label><label>项目SOP版本 / 积分产品参数<input name="sop" maxlength="100" placeholder="项目填写版本；积分产品填：积分数,库存数，例如50,10"></label><label class="full">图片链接<input name="image" placeholder="https://…或上传后自动填入"></label><label class="full">上传展示图片<input id="contentImage" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="uploadImage" class="btn secondary" type="button">上传并填入图片链接</button><label class="full">跳转链接 / 视频地址<input name="link" placeholder="有效HTTPS链接；科普可填公众号文章"></label><div class="full" id="giftFields" hidden><label>积分品类<select name="giftCategory"><option value="household_wash">家用洗护</option><option value="hygiene_care">卫生护理</option><option value="home_textiles">家居棉纺</option><option value="appliances">家电类</option><option value="daily_goods">日用小商品</option><option value="strollers_beds">车床类</option><option value="educational_toys">益智玩具</option><option value="wellness_services">养生服务类</option></select></label><label>兑换积分<input name="giftPoints" type="number" min="0" max="9999999"></label><label>库存<input name="giftStock" type="number" min="0" max="9999999"></label></div><label class="full">咨询二维码图片链接<input name="qr" placeholder="已核验的二维码图片链接"></label></div><label class="check"><input name="published" type="checkbox">公开发布（不勾选则保存草稿）</label><label class="check"><input name="confirmed" type="checkbox" required>资料真实且已核验，拥有展示授权；技术SOP全文不会填入公开介绍。</label><div class="actions"><button class="btn" type="submit">保存资料</button><button type="reset" class="btn secondary">新建 / 清空</button></div><p id="saveStatus" class="status" role="status"></p></form><div id="contentRecords" style="margin-top:32px"></div></div>`);}

const cooperationSteps=[['点击联系我们共建数字门店','从页面按钮开始，开启合作沟通。'],['填写合作意向登记','留下姓名、联系方式和所在地区。'],['平台联系你','工作人员联系，了解资源与需求。'],['互相了解合作事宜','沟通空间、人员、项目与合作方式。'],['达成合作共识并签约','明确双方责任、支持内容与分配约定。'],['完成数字门店共建','共同确认门店空间、设备与服务接待。'],['完成服务体系共建','落实项目、人员、标准流程与培训。'],['相关信息录入数字平台','录入门店、技师、项目与预约信息。'],['陪跑运营','共同复盘服务与运营，持续优化。']];
function cooperationScreen(){return section('荷序平台标准化合作流程',`<div class="cooperation-player"><div id="cooperationSlides" aria-live="off">${cooperationSteps.map(([t,d],i)=>`<article class="flow-slide ${i===0?'active':''}"><span class="flow-number">${String(i+1).padStart(2,'0')} / 09</span><p class="eyebrow">从合作意向，到共同运营</p><h2>${t}</h2><p>${d}</p>${i===0?`<div class="actions">${a('联系我们共建数字门店','join.html')}</div>`:''}</article>`).join('')}</div><video id="cooperationVideo" controls playsinline hidden></video><div class="flow-controls"><button id="flowPrev">上一步</button><span id="flowCount">1 / 9</span><button id="flowNext">下一步</button><button id="flowPause">暂停播放</button><button id="flowDefault" hidden>查看合作流程</button></div><div id="flowMediaChoices" class="actions"></div></div>`);}
const projectPreview=[['母乳喂养指导','了解哺乳姿势、亲子互动与日常喂养支持。'],['安心催眠','在专业引导下体验放松与身心支持。'],['小儿推拿','了解服务场景与专业人员，先沟通再预约。']].map(([title,description],i)=>({id:'preview-'+i,kind:'project',title,description,city:'场景预览',image:'assets/project-scene-'+i+'.jpg',tags:'场景示意',sop:'正式开放信息待审核',sample:true}));
function projectScenes(){return section('先了解服务，再做选择',`<div class="scene-player">${projectPreview.map((x,i)=>`<article class="scene-slide ${i===0?'active':''}">${photo(x.image,x.title+'场景示意')}<div><p class="eyebrow">服务场景 · AI示意图</p><h2>${x.title}</h2><p>${x.description}</p></div></article>`).join('')}</div><div class="actions">${projectPreview.map((x,i)=>`<button class="btn secondary" data-scene-index="${i}">${x.title}</button>`).join('')}<button class="btn secondary" id="scenePause">暂停播放</button></div><p class="caption">图片为场景示意，不代表真实案例；服务内容与提供人员以正式项目为准。</p>`);}
function priority(x){return Number((x.tags||'').match(/priority:(\d+)/)?.[1]||0);}
main.innerHTML=({home,about,guide,stores,projects,training,health,points,disputes,contact,admin,showcase,apply:()=>title('申请合作','带着你的资源，从一个项目开始。')+section('填写合作信息',applyForm(false)),join:()=>title('联系我们共建数字门店','一起评估社区需求、空间与专业资源。')+section('填写共建意向',applyForm(true))}[page]||home)();
const nav=$(`[data-nav="${page}"]`);if(nav){nav.classList.add('active');nav.setAttribute('aria-current','page');}
if(C.loginUrl&&url(C.loginUrl))$('#accountEntry').href=url(C.loginUrl);
const dialog=$('#detailDialog');$('#closeDetail').onclick=()=>dialog.close();
function openDetail(t,b){$('#detailTitle').textContent=t;$('#detailBody').innerHTML=b;dialog.showModal();}
async function readJSON(u){const r=await fetch(u,{cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'暂时无法读取，请重试');return d;}
function mediaError(){document.querySelectorAll('img').forEach(im=>im.addEventListener('error',()=>{const p=document.createElement('div');p.className='photo-empty';p.textContent='图片暂时无法加载';im.replaceWith(p);},{once:true}));}
function recordCard(x){return `<article class="card">${photo(x.image,x.kind==='project'?'项目操作与服务图片':'已核验资料图片')}<div class="card-body"><span class="tag ${x.sample?'sample':''}">${x.sample?'展示样例':e(x.city||'已发布资料')}</span><h3>${e(x.title)}</h3><p>${e(x.description.slice(0,110))}${x.description.length>110?'…':''}</p>${x.kind==='project'?`<p class="caption">标准信息：${e(x.sop)}</p>`:''}<div class="chips">${(x.tags||'').split(/[,，]/).filter(Boolean).slice(0,3).map(t=>`<span class="tag">${e(t)}</span>`).join('')}</div><button class="btn secondary" data-record="${e(x.id)}">${x.kind==='article'?'查看问题与咨询入口':'查看介绍'}</button></div></article>`;}
let currentRecords=[];
function bindRecords(rows){currentRecords=rows;document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{const x=currentRecords.find(r=>r.id===b.dataset.record);if(!x)return;openDetail(x.title,`${x.sample?'<p class="notice">这是布局与筛选演示，不代表实际项目已经开放。</p>':''}${x.image?photo(x.image,x.title):''}<p class="text-block" style="margin-top:20px">${e(x.description)}</p>${x.sop?`<p class="caption">标准信息：${e(x.sop)} · 完整SOP按技术人员权限开放</p>`:''}<div class="qr-slot">${x.qr?`<img src="${e(url(x.qr))}" alt="${e(x.title)}咨询二维码"><p>识别二维码，查看对应咨询指引</p>`:'咨询二维码将在核验后发布'}</div><div class="actions">${x.link&&url(x.link)?a(x.kind==='article'?'阅读公众号文章':'查看相关服务',x.link):''}${a(x.sample?'了解合作':'联系平台','contact.html','secondary')}</div>`);mediaError();});}
function fillCities(select,rows,first='全部地区'){const previous=select.value;select.replaceChildren(new Option(first,'all'));[...new Set(rows.map(x=>x.city||x.region).filter(Boolean))].sort().forEach(c=>select.add(new Option(c,c)));if([...select.options].some(o=>o.value===previous))select.value=previous;}
async function content(){try{const d=await readJSON(C.contentUrl||'/api/showcase');catalog=d.items||[];if(C.projectsUrl||C.techniciansUrl){const results=await Promise.allSettled([C.projectsUrl?readJSON(C.projectsUrl):Promise.resolve(null),C.techniciansUrl?readJSON(C.techniciansUrl):Promise.resolve(null)]);for(let i=0;i<results.length;i++){const r=results[i],kind=i===0?'project':'technician';if(r.status==='fulfilled'&&r.value){const rows=r.value.items;if(!Array.isArray(rows))throw Error('目录接口格式不正确');catalog=catalog.filter(x=>x.kind!==kind).concat(rows.filter(x=>x.published!==false).map(x=>({...x,kind,description:String(x.description||''),tags:String(x.tags||'')})));}else if(r.status==='rejected')loadError=true;}}loaded=true;$('#adminEntry').hidden=!d.isOwner;if(d.isOwner&&$('#storeAdmin'))$('#storeAdmin').hidden=false;}catch{loaded=true;loadError=true;}}
function renderProjects(sample=false){const actual=catalog.filter(x=>x.kind==='project');const rows=sample?projectPreview:actual.length?actual:projectPreview;fillCities($('#projectCity'),rows,sample?'全部样例城市':'全部已开展城市');const show=rows.filter(x=>$('#projectCity').value==='all'||x.city===$('#projectCity').value);$('#projectStatus').textContent=(sample||!actual.length)?'场景展示样例 · 实际开放项目以所在城市发布信息为准。':loadError?'项目目录暂时无法加载，请刷新重试。':`${rows.length} 个已发布项目；完整技术SOP按账号权限开放。`;$('#projectGrid').innerHTML=show.length?show.map(recordCard).join(''):empty('这个城市的项目尚未发布','真实项目完成筛选与标准审核后显示在这里。',a('联系合作','cooperation-apply.html','secondary'));bindRecords(show);mediaError();}
function renderPeople(kind,target,city){const rows=catalog.filter(x=>x.kind===kind);if(city)fillCities($(city),rows);const show=rows.filter(x=>!city||$(city).value==='all'||x.city===$(city).value);$(target).innerHTML=show.length?show.map(recordCard).join(''):empty(loadError?'资料暂时无法读取':'专业资料正在审核与整理',kind==='advisor'?'已入驻公益顾问资料将在核验并取得本人授权后展示。':'各地区技术人员的专长、服务城市与介绍将在核验后发布。',a('联系合作','cooperation-apply.html','secondary'));bindRecords(catalog);mediaError();}
function renderArticles(topic='全部'){const rows=catalog.filter(x=>x.kind==='article'&&(topic==='全部'||x.tags.includes(topic)));$('#articleGrid').innerHTML=rows.length?rows.map(recordCard).join(''):empty(loadError?'健康内容暂时无法读取':'该主题内容待发布','科普文章将由后台录入，每个健康问题可配置专属咨询二维码。',a('联系平台','contact.html','secondary'));bindRecords(catalog);mediaError();}
function bindVideo(){document.querySelectorAll('[data-video-src]').forEach(b=>b.onclick=()=>{const src=url(b.dataset.videoSrc);if(!src)return;const v=$('#platformVideo');v.pause();v.src=src;v.load();document.querySelectorAll('[data-video-src]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#videoNote').textContent=b.textContent;});}
async function setupVideos(){if(!$('#platformVideo'))return;bindVideo();if(!loaded)await content();const list=$('#publishedVideos');if(list){list.innerHTML=catalog.filter(x=>x.kind==='video'&&url(x.link)&&(!x.tags||x.tags.split(/[,，]/).includes(page))).map(x=>`<button data-video-src="${e(x.link)}" aria-pressed="false">${e(x.title)}</button>`).join('');bindVideo();}}
async function access(){const status=$('#unlockStatus'),grid=$('#authorizedFiles');if(!grid)return;status.textContent='正在核对账号权限…';try{const d=await readJSON('/api/guide?action=content');const scope=grid.dataset.scope,rows=d.templates.filter(x=>x.canAccess&&(scope!=='training'||x.category==='training'));grid.innerHTML=rows.map(x=>card(e(x.title),'此文件已授权给当前账号，可查看或下载。','已授权','',a('下载资料','/api/guide?action=file&id='+encodeURIComponent(x.id),'secondary')+(x.mime==='application/pdf'?a('查看PDF','/api/guide?action=file&view=1&id='+encodeURIComponent(x.id),'secondary'):''))).join('');status.textContent=rows.length?`已找到 ${rows.length} 份授权资料。`:'当前账号暂无对应资料权限，请联系平台开通。';}catch(err){status.textContent=err.message;}}
function setupLock(){if(!$('#unlockForm'))return;$('#checkAccess').onclick=access;$('#unlockForm').onsubmit=async ev=>{ev.preventDefault();const code=ev.currentTarget.elements.code.value;if(!code){$('#unlockStatus').textContent='请填写解锁码，或直接验证账号权限。';return;}const b=ev.submitter;b.disabled=true;try{const r=await fetch(C.partnerUnlockUrl||'/api/showcase?action=unlock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});const d=await r.json();if(!r.ok)throw Error(d.error||'验证失败');await access();}catch(err){$('#unlockStatus').textContent=err.message;}finally{b.disabled=false;}};}
function switchGuide(kind){document.querySelectorAll('[data-guide]').forEach(b=>b.classList.toggle('active',b.dataset.guide===kind));$('#guideView').innerHTML=({customer:guideCustomer,partner:guidePartner,operations:guideOperations}[kind]||guideCustomer)();setupLock();setupVideos();if(kind==='partner')fetch('service-guide-data.json').then(r=>r.json()).then(d=>{$('#cooperationServices').innerHTML=d.services.map(s=>`<details><summary>${e(s.title)}</summary><p>${e(s.summary)}</p><h3 style="margin-top:18px">平台提供</h3><ul>${s.deliverables.map(x=>`<li>${e(x)}</li>`).join('')}</ul><h3>合作要求</h3><ul>${s.requirements.map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>交付：${e(s.outputs)}</p><div class="actions">${a('申请此项合作','cooperation-apply.html?interest='+s.id,'secondary')}</div></details>`).join('');}).catch(()=>{$('#cooperationServices').textContent='合作说明暂时无法读取，请刷新重试。';});}
async function setupForm(){const form=$('#applicationForm');if(!form)return;const p=$('#province'),c=$('#city'),a0=$('#county'),status=$('#applicationStatus');let areas;
const fill=(sel,rows,head)=>{sel.replaceChildren(new Option(head,''));Object.entries(rows).forEach(([code,n])=>sel.add(new Option(n,code)));sel.disabled=false;};
try{areas=await readJSON('area-data.json');fill(p,areas.province_list,'选择省份');}catch{status.textContent='地区列表无法加载，请刷新重试。';return;}
p.onchange=()=>{c.replaceChildren(new Option('选择城市',''));a0.replaceChildren(new Option('选择区县',''));c.disabled=a0.disabled=true;if(p.value)fill(c,Object.fromEntries(Object.entries(areas.city_list).filter(([code])=>code.slice(0,2)===p.value.slice(0,2))),'选择城市');};c.onchange=()=>{a0.replaceChildren(new Option('选择区县',''));a0.disabled=true;if(c.value)fill(a0,Object.fromEntries(Object.entries(areas.county_list).filter(([code])=>code.slice(0,4)===c.value.slice(0,4))),'选择区县');};
if($('#applicantType')){$('#applicantType').onchange=()=>{const other=$('#applicantType').value==='other';$('#otherField').hidden=!other;$('#otherType').disabled=!other;$('#otherType').required=other;};const interest=new URLSearchParams(location.search).get('interest');if(interest&&[...form.elements.interest.options].some(o=>o.value===interest))form.elements.interest.value=interest;}
form.onsubmit=async ev=>{ev.preventDefault();if(!form.reportValidity())return;const b=ev.submitter;b.disabled=true;status.textContent='正在提交…';const d=Object.fromEntries(new FormData(form));Object.assign(d,{provinceCode:p.value,cityCode:c.value,countyCode:a0.value,consent:form.elements.consent.checked});const join=form.dataset.join==='true';if(!join)d.interests=[d.interest];try{const r=await fetch(join?'/api/leads':'/api/guide?action=apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const result=await r.json();if(!r.ok)throw Error(result.error||'提交失败');status.textContent=result.message||'已收到合作意向';form.reset();c.disabled=a0.disabled=true;if($('#otherField')){$('#otherField').hidden=true;$('#otherType').disabled=true;$('#otherType').required=false;}}catch(err){status.textContent=err.message||'提交失败，请保留内容后重试';}finally{b.disabled=false;}};}
let storeRows=[],storeTotal=0,storeNext=null,storeLimit=3;
function renderStores(){const area=$('#storeCity').value;const rows=storeRows.filter(x=>area==='all'||x.region===area);$('#storeGrid').innerHTML=rows.length?rows.slice(0,storeLimit).map(x=>`<article class="card">${photo(x.coverUrl,x.name+'门头')}${photo(x.interiorUrls?.[0],x.name+'内部场景')}<div class="card-body"><span class="tag">${e(x.region)}</span><h3>${e(x.name)}</h3><p>${e(x.description.slice(0,130))}</p><div class="chips">${x.projects.slice(0,3).map(p=>`<span class="tag">${e(p.title)}</span>`).join('')}</div><button class="btn secondary" data-store="${e(x.id)}">门店环境与特色项目</button></div></article>`).join(''):[1,2,3].map(n=>`<article class="card store-slot"><div class="photo-empty">门头照片 ${n}</div><div class="photo-empty interior-slot">门店内场景照片</div><div class="card-body"><h3>合作门店展示位 ${n}</h3><p>门店简介与擅长项目待发布</p>${a('联系合作','cooperation-apply.html','secondary')}</div></article>`).join('');$('#storeStatus').textContent=`${storeTotal} 家已发布门店 · 当前地区展示 ${Math.min(storeLimit,rows.length)} 家`;
$('#moreStores').hidden=storeLimit>=rows.length&&storeNext===null;
document.querySelectorAll('[data-store]').forEach(b=>b.onclick=()=>{const x=storeRows.find(s=>s.id===b.dataset.store);openDetail(x.name,`<p>${e(x.region)}</p><div class="grid two" style="margin-top:20px">${photo(x.coverUrl,'门头照片')}${photo(x.interiorUrls[0],'内部环境')}</div><p class="text-block" style="margin-top:20px">${e(x.description)}</p><h3 style="margin-top:24px">擅长项目</h3>${x.projects.map(p=>`<details open><summary>${e(p.title)}</summary><p>${e(p.description)}</p></details>`).join('')}<div class="actions">${a('了解对应项目','projects.html')}${a('联系合作','cooperation-apply.html','secondary')}</div>`);mediaError();});mediaError();}
async function loadStores(offset=0){try{const endpoint=new URL(C.storesUrl||'/api/stores',location.origin);endpoint.searchParams.set('offset',offset);if($('#storeCity').value!=='all')endpoint.searchParams.set('region',$('#storeCity').value);const d=await readJSON(endpoint);if(offset===0)storeRows=d.stores;else{const ids=new Set(storeRows.map(x=>x.id));storeRows.push(...d.stores.filter(x=>!ids.has(x.id)));}storeTotal=d.total;storeNext=d.nextOffset??null;fillCities($('#storeCity'),d.regions?d.regions.map(region=>({region})):storeRows);$('#storeAdmin').hidden=!d.isOwner;renderStores();}catch(err){$('#storeStatus').textContent=err.message;$('#storeGrid').innerHTML=empty('门店目录暂时无法读取','请稍后刷新；下方可查看社区门店空间样板。');$('#moreStores').hidden=true;}}
let giftData=null,giftCategory='all',giftPreview=true;
function renderGifts(){const cats=giftData.categories;$('#giftCategories').innerHTML=cats.map(x=>`<button class="${giftCategory===x.id?'active':''}" data-gift-category="${e(x.id)}">${e(x.name)}<small>${e(x.description||'点击查看兑换产品')}</small></button>`).join('');const rows=giftCategory==='all'?[]:giftData.items.filter(x=>giftCategory==='all'||x.categoryId===giftCategory);$('#giftStatus').textContent=giftPreview?'品类展示样例：商品积分、图片及库存审核后发布；暂不接受真实兑换。':'上架产品按分类展示；兑换需通过正式账户系统确认。';$('#giftGrid').innerHTML=rows.length?rows.map(x=>`<article class="card">${photo(x.imageUrl,x.title+'图片待录入')}<div class="card-body"><span class="tag ${giftPreview?'sample':''}">${giftPreview?'品类样例':e(cats.find(c=>c.id===x.categoryId)?.name||'兑换好物')}</span><h3>${e(x.title)}</h3><p>${Number.isFinite(x.pointsPrice)?e(x.pointsPrice)+' 积分':'兑换积分待发布'}</p><p class="caption">${Number.isFinite(x.stock)?x.stock>0?'库存 '+e(x.stock):'暂时缺货':'库存待发布'}</p><button class="btn secondary" data-gift="${e(x.id)}">查看兑换说明</button></div></article>`).join(''):empty(giftCategory==='all'?'选择一类，看看生活好物':'这一类暂无可兑换好物',giftCategory==='all'?'点击上方分类，查看该类已上架产品。':'积分无有效期，有库存后再来挑选。');
document.querySelectorAll('[data-gift-category]').forEach(b=>b.onclick=()=>{giftCategory=b.dataset.giftCategory;renderGifts();});document.querySelectorAll('[data-gift]').forEach(b=>b.onclick=()=>{const x=giftData.items.find(i=>i.id===b.dataset.gift);openDetail(x.title,`${x.imageUrl?photo(x.imageUrl,x.title):''}<p style="margin-top:18px">${giftPreview?'此条为品类样例。正式发布后显示兑换积分、库存与配送说明。':e(x.description||'请核对兑换积分、库存与领取方式。')}</p><p class="caption">领取方式：${(x.fulfillmentModes||[]).map(m=>m==='delivery'?'邮寄':m==='pickup'?'社区领取':'服务预约').join(' / ')||'详情发布后确认'}</p><div class="notice">${giftPreview?'当前不能兑换。积分商城将按建设进度开放。':'缺货或积分不足时不能兑换。确认前请核对领取地点、配送地区及可能产生的运费。'}</div>${!giftPreview&&C.rewardCheckoutUrl&&x.stock>0&&Number.isFinite(x.pointsPrice)?`<button class="btn" id="redeemGift">前往确认兑换</button>`:a('联系平台','contact.html','secondary')}`);if($('#redeemGift'))$('#redeemGift').onclick=async()=>{const status=document.createElement('p');status.className='status';$('#detailBody').append(status);$('#redeemGift').disabled=true;try{const r=await fetch(C.rewardCheckoutUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemId:x.id,quantity:1,idempotencyKey:crypto.randomUUID()})});const d=await r.json();if(!r.ok||!d.checkoutUrl||!url(d.checkoutUrl))throw Error(d.error||'无法创建兑换确认');location.href=url(d.checkoutUrl);}catch(err){status.textContent=err.message;$('#redeemGift').disabled=false;}};mediaError();});mediaError();}
async function setupGifts(){try{giftPreview=!C.rewardCatalogUrl;giftData=await readJSON(C.rewardCatalogUrl||'rewards-preview.json');if(!C.rewardCatalogUrl){await content();giftData.items=catalog.filter(x=>x.kind==='gift').map(x=>({id:x.id,categoryId:x.tags,title:x.title,description:x.description,imageUrl:x.image,pointsPrice:Number(x.sop.split(',')[0]),stock:Number(x.sop.split(',')[1]),fulfillmentModes:['delivery','pickup']}));giftPreview=false;}renderGifts();}catch(err){$('#giftStatus').textContent=err.message;}if(C.pointsAccountUrl)try{const d=await readJSON(C.pointsAccountUrl);if(!Number.isFinite(d.availablePoints)||!Number.isFinite(d.pendingPoints))throw Error();$('#balance').textContent=d.availablePoints;$('#pending').textContent=d.pendingPoints;$('#walletStatus').textContent='已读取当前账户积分。';}catch{$('#walletStatus').textContent='账户积分暂时无法读取，请稍后重试。';}}
async function notices(){const reads=await Promise.allSettled([readJSON('/api/leads'),readJSON('/api/guide?action=admin'),readJSON('/api/disputes')]);const data=reads.map(r=>r.status==='fulfilled'?r.value:null);const count=data.reduce((s,x)=>s+(x?.pendingCount||0),0);if(count){$('#contactBadge').hidden=false;$('#contactBadge').textContent=`待联系 ${count}`;}
if(page==='contact'&&data.some(Boolean)){$('#contactAdmin').hidden=false;$('#pendingSummary').innerHTML=[['门店共建',data[0]?.pendingCount||0],['合作申请',data[1]?.pendingCount||0],['服务反馈',data[2]?.pendingCount||0]].map(([t,n])=>`<article>${t}<strong>${n}</strong></article>`).join('');let records='';for(const x of data[0]?.leads||[])records+=`<div class="admin-record"><h3>门店共建：${e(x.name)}</h3><p>${e(x.phone)} · ${e(x.province)} ${e(x.city)} ${e(x.county)}</p><p class="caption">${e(x.createdAt)} · ${x.status==='new'?'待联系':'已联系'}</p>${x.status==='new'?`<button class="btn secondary" data-contacted="${x.id}">标记已联系</button>`:''}</div>`;
for(const x of data[1]?.applications||[])records+=`<div class="admin-record"><h3>合作申请：${e(x.name)}</h3><p>${e(x.phone)} · ${e(x.province)} ${e(x.city)} ${e(x.county)}</p><p>${e(x.message)}</p><p class="caption">${x.status==='new'?'待联系':'已联系'}</p>${x.status==='new'?`<button class="btn secondary" data-application-contacted="${x.id}">标记已联系</button>`:''}</div>`;
for(const x of data[2]?.records||data[2]?.disputes||[])records+=`<div class="admin-record"><h3>服务反馈：${e(x.name)}</h3><p>${e(x.phone)} · 订单 ${e(x.orderRef||x.order_ref)}</p><p>${e(x.description)}</p>${x.status==='new'?`<button class="btn secondary" data-dispute-contacted="${x.id}">标记已联系</button>`:''}</div>`;$('#leadRecords').innerHTML=records||'<p>暂无提交信息。</p>';for(const [selector,endpoint,key] of [['[data-application-contacted]','/api/guide','applicationContacted'],['[data-dispute-contacted]','/api/disputes','disputeContacted']])document.querySelectorAll(selector).forEach(b=>b.onclick=async()=>{b.disabled=true;try{const body={id:Number(b.dataset[key]),action:'contacted'};const r=await fetch(endpoint,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error();await notices();}catch{b.textContent='保存失败，请重试';b.disabled=false;}});document.querySelectorAll('[data-contacted]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await fetch('/api/leads',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:Number(b.dataset.contacted)})});if(!r.ok)throw Error();await notices();}catch{b.textContent='保存失败，请重试';b.disabled=false;}});}}
async function setupAdmin(){const status=$('#adminStatus');if(!status)return;try{const d=await readJSON('/api/showcase?admin=1');$('#adminPanel').hidden=false;status.textContent='当前账号具备发布权限。';const form=$('#contentForm');let rows=d.items;const giftFields=$('#giftFields');const updateGiftFields=()=>{const on=form.elements.kind.value==='gift';giftFields.hidden=!on;form.elements.giftPoints.required=on;form.elements.giftStock.required=on;};form.elements.kind.onchange=updateGiftFields;
function records(){ $('#contentRecords').innerHTML=rows.map(x=>`<div class="admin-record"><span class="tag">${x.published?'已发布':'草稿'} · ${e(x.kind)}</span><h3>${e(x.title)}</h3><p>${e(x.city)} · ${e(x.description.slice(0,70))}</p><button class="btn secondary" data-edit="${e(x.id)}">编辑资料</button><button class="btn secondary" data-delete="${e(x.id)}">删除资料</button></div>`).join('');document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const x=rows.find(r=>r.id===b.dataset.edit);['id','kind','city','title','description','image','link','qr','tags','sop'].forEach(k=>form.elements[k].value=x[k]||'');form.elements.published.checked=Boolean(x.published);if(x.kind==='gift'){form.elements.giftCategory.value=x.tags;const parts=x.sop.split(',');form.elements.giftPoints.value=parts[0];form.elements.giftStock.value=parts[1];}updateGiftFields();form.elements.confirmed.checked=false;form.scrollIntoView({behavior:'smooth'});});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('确认删除这条资料？'))return;b.disabled=true;try{const r=await fetch('/api/showcase?id='+encodeURIComponent(b.dataset.delete),{method:'DELETE'});if(!r.ok)throw Error('删除失败');rows=rows.filter(x=>x.id!==b.dataset.delete);records();}catch(err){$('#saveStatus').textContent=err.message;b.disabled=false;}});}records();
$('#uploadImage').onclick=async()=>{const file=$('#contentImage').files[0];if(!file){$('#saveStatus').textContent='请先选择图片。';return;}const fd=new FormData();fd.set('file',file);const b=$('#uploadImage');b.disabled=true;try{const r=await fetch('/api/stores?action=image',{method:'POST',body:fd});const d=await r.json();if(!r.ok)throw Error(d.error);form.elements.image.value=d.url;$('#saveStatus').textContent='图片已上传，保存资料后公开展示。';}catch(err){$('#saveStatus').textContent=err.message;}finally{b.disabled=false;}};
form.onsubmit=async ev=>{ev.preventDefault();if(!form.reportValidity())return;const b=ev.submitter;b.disabled=true;const d=Object.fromEntries(new FormData(form));if(d.kind==='gift'){d.tags=d.giftCategory;d.sop=d.giftPoints+','+d.giftStock;}d.published=form.elements.published.checked;d.confirmed=form.elements.confirmed.checked;try{const r=await fetch('/api/showcase',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const result=await r.json();if(!r.ok)throw Error(result.error);$('#saveStatus').textContent=result.message;form.elements.id.value=result.id;rows=(await readJSON('/api/showcase?admin=1')).items;records();}catch(err){$('#saveStatus').textContent=err.message;}finally{b.disabled=false;}};
}catch(err){status.textContent=err.message;}}
function renderShowcase(){const all=catalog.filter(x=>['technician','scene'].includes(x.kind));fillCities($('#techCity'),all);const city=$('#techCity').value;const visible=all.filter(x=>city==='all'||x.city===city);for(const [kind,target,label] of [['technician','#technicianGrid','优秀技师资料'],['scene','#sceneGrid','服务场景资料']]){const rows=visible.filter(x=>x.kind===kind).sort((a,b)=>priority(b)-priority(a)).slice(0,kind==='technician'?3:500);$(target).innerHTML=rows.length?rows.map(recordCard).join(''):empty(loadError?'资料暂时无法读取':label+'待发布','审核后的资料将在这里显示。',a('联系合作','cooperation-apply.html','secondary'));}bindRecords(visible);mediaError();}
function setupHero(){const root=$('.hero-carousel');if(!root)return;const slides=[...root.querySelectorAll('[data-hero-slide]')],dots=[...root.querySelectorAll('[data-hero-dot]')],reduce=matchMedia('(prefers-reduced-motion:reduce)');let i=0,timer=null,playing=!reduce.matches,hover=false,focus=false;const toggle=root.querySelector('.hero-toggle');function show(n,manual=false){i=(n+slides.length)%slides.length;slides.forEach((x,j)=>{x.classList.toggle('active',j===i);x.setAttribute('aria-hidden',String(j!==i));x.inert=j!==i;});dots.forEach((x,j)=>x.setAttribute('aria-pressed',String(j===i)));if(manual)$('#heroStatus').textContent='第'+(i+1)+'屏：'+slides[i].querySelector('h1').textContent;}function sync(){clearInterval(timer);timer=null;toggle.textContent=playing?'暂停轮播':'播放轮播';if(playing&&!hover&&!focus&&!document.hidden)timer=setInterval(()=>show(i+1),6500);}root.querySelector('.hero-prev').onclick=()=>{show(i-1,true);sync();};root.querySelector('.hero-next').onclick=()=>{show(i+1,true);sync();};dots.forEach(b=>b.onclick=()=>{show(Number(b.dataset.heroDot),true);sync();});toggle.onclick=()=>{playing=!playing;sync();};root.addEventListener('mouseenter',()=>{hover=true;sync();});root.addEventListener('mouseleave',()=>{hover=false;sync();});root.addEventListener('focusin',()=>{focus=true;sync();});root.addEventListener('focusout',()=>setTimeout(()=>{focus=root.contains(document.activeElement);sync();},0));document.addEventListener('visibilitychange',sync);reduce.addEventListener('change',()=>{if(reduce.matches)playing=false;sync();});show(0);sync();}
if(page==='showcase'){content().then(renderShowcase);$('#techCity').onchange=renderShowcase;}
setupHero();
if(page==='guide'){document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>switchGuide(b.dataset.guide));switchGuide(location.hash==='#operations'?'operations':location.hash==='#partner'?'partner':'customer');}
if(page==='stores'){loadStores();$('#storeCity').onchange=()=>{storeLimit=3;loadStores();};$('#moreStores').onclick=async()=>{storeLimit+=12;if(storeNext!==null)await loadStores(storeNext);else renderStores();};}
if(page==='projects'){let sample=false;content().then(()=>renderProjects(sample));$('#projectCity').onchange=()=>renderProjects(sample);$('#projectSample').onclick=()=>{sample=!sample;$('#projectSample').textContent=sample?'返回已发布项目':'查看展示样例';renderProjects(sample);};}
if(page==='training'){setupLock();content().then(()=>renderPeople('technician','#technicianGrid','#techCity'));$('#techCity').onchange=()=>renderPeople('technician','#technicianGrid','#techCity');}
if(page==='health'){content().then(()=>{renderArticles();renderPeople('advisor','#advisorGrid');});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-topic]').forEach(x=>x.classList.toggle('active',x===b));renderArticles(b.dataset.topic);});}
if(page==='points')setupGifts();if(page==='admin')setupAdmin();if($('#applicationForm'))setupForm();
if(page==='disputes'){const f=$('#disputeForm');f.onsubmit=async ev=>{ev.preventDefault();if(!f.reportValidity())return;const b=ev.submitter;b.disabled=true;const d=Object.fromEntries(new FormData(f));d.consent=f.elements.consent.checked;$('#formStatus').textContent='正在提交…';try{const r=await fetch('/api/disputes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});const result=await r.json();if(!r.ok)throw Error(result.error);$('#formStatus').textContent=result.message;f.reset();}catch(err){$('#formStatus').textContent=err.message;}finally{b.disabled=false;}};}
setupVideos();notices();mediaError();

function startPlayback(root,slides,prev,next,pause,count,delay=5500){let i=0,playing=!matchMedia('(prefers-reduced-motion:reduce)').matches;const show=n=>{i=(n+slides.length)%slides.length;slides.forEach((x,j)=>{x.classList.toggle('active',j===i);x.inert=j!==i;x.setAttribute('aria-hidden',String(j!==i));});if(count)count.textContent=(i+1)+' / '+slides.length;};const sync=()=>{if(pause)pause.textContent=playing?'暂停播放':'继续播放';};if(prev)prev.onclick=()=>show(i-1);if(next)next.onclick=()=>show(i+1);if(pause)pause.onclick=()=>{playing=!playing;sync();};setInterval(()=>{if(playing&&!document.hidden&&!root.matches(':hover')&&!root.contains(document.activeElement))show(i+1);},delay);show(0);sync();return show;}
if(page==='about'){const root=$('.cooperation-player');startPlayback(root,[...root.querySelectorAll('.flow-slide')],$('#flowPrev'),$('#flowNext'),$('#flowPause'),$('#flowCount'));content().then(()=>{const rows=catalog.filter(x=>x.kind==='video'&&(x.tags||'').split(/[,，]/).includes('about')&&url(x.link));$('#flowMediaChoices').innerHTML=rows.map(x=>`<button class="btn secondary" data-flow-video="${e(x.id)}">${e(x.title)}</button>`).join('');const reset=()=>{$('#cooperationVideo').pause();$('#cooperationVideo').hidden=true;$('#cooperationSlides').hidden=false;$('#flowDefault').hidden=true;};$('#flowDefault').onclick=reset;document.querySelectorAll('[data-flow-video]').forEach(b=>b.onclick=()=>{const x=rows.find(x=>x.id===b.dataset.flowVideo);$('#cooperationSlides').hidden=true;$('#cooperationVideo').hidden=false;$('#cooperationVideo').src=url(x.link);$('#flowDefault').hidden=false;});});}
if(page==='projects'){const root=$('.scene-player');const show=startPlayback(root,[...root.querySelectorAll('.scene-slide')],null,null,$('#scenePause'),null);document.querySelectorAll('[data-scene-index]').forEach(b=>b.onclick=()=>show(Number(b.dataset.sceneIndex)));}
if(page==='health'){const strip=$('#advisorGrid');let playing=!matchMedia('(prefers-reduced-motion:reduce)').matches;$('#advisorPrev').onclick=()=>strip.scrollBy({left:-340,behavior:'smooth'});$('#advisorNext').onclick=()=>strip.scrollBy({left:340,behavior:'smooth'});$('#advisorPause').textContent=playing?'暂停轮播':'继续轮播';$('#advisorPause').onclick=()=>{playing=!playing;$('#advisorPause').textContent=playing?'暂停轮播':'继续轮播';};setInterval(()=>{if(playing&&!document.hidden&&!strip.matches(':hover')&&!strip.contains(document.activeElement))strip.scrollTo({left:strip.scrollLeft+strip.clientWidth>=strip.scrollWidth-8?0:strip.scrollLeft+340,behavior:'smooth'});},5500);content().then(()=>{const q=catalog.find(x=>x.kind==='qr'&&url(x.qr||x.image));if(q)$('#communityQR').innerHTML=`<img src="${e(url(q.qr||q.image))}" alt="添加荷序工作人员二维码">`;});}
if(page==='home'&&!C.orderUrl){const service=[...document.querySelectorAll('.quick a')][0];service.href='client-entry.html';}
})();
